const allowed = new Set(['cbox', 'unmapped']);
const isRaw = /^raw\/[a-z0-9][a-z0-9/_-]*$/i.test(msg.topic || '');
const channel = (allowed.has(msg.topic) || isRaw) ? msg.topic : 'misc';
const d = new Date();
const yyyy = d.getUTCFullYear();
const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
const dd = String(d.getUTCDate()).padStart(2, '0');
msg.filename = `/timeseries/${channel}/${yyyy}-${mm}-${dd}.jsonl`;
msg.payload = JSON.stringify(msg.payload);
return msg;
